        const adjustPosition = () => {
          const actualH = Math.max(modalImage.offsetHeight + 40, 400);
          let adjustedTop = imgCenterAbs - actualH / 2;
          if (adjustedTop < 0) adjustedTop = 0;
          modal.style.top = adjustedTop + 'px';
          modal.style.height = actualH + 'px';
        };

        modalImage.onload = adjustPosition;
        modalImage.onerror = () => {
          if (modalImageSource.src !== modalImageSource.fallbackSrc) {
            modalImage.onerror = null;
            modalImage.onload = adjustPosition;
            modalImage.src = modalImageSource.fallbackSrc;
          } else {
            adjustPosition();
          }
        };

