      for (const [name, config] of Object.entries(CHARACTER_CONFIG)) {
        if (config.aliases && config.aliases.some(alias =>
          alias.toLowerCase() === s.toLowerCase() ||
          new RegExp(`^${alias}$`, 'i').test(s)
        )) {
          return name;
        }
      }

      // 2. 尝试模糊匹配（包含别名），取最长匹配
      // 解决类似“视频中的蕾雅”这样的情况
      let bestMatch = null;
      let maxLen = 0;

      for (const [name, config] of Object.entries(CHARACTER_CONFIG)) {
        if (!config.aliases) continue;
        for (const alias of config.aliases) {
          // 跳过单字符别名（如'我'、'你'），避免误匹配
          if (alias.length < 2) continue;
          if (s.includes(alias)) {
            if (alias.length > maxLen) {
              maxLen = alias.length;
              bestMatch = name;
            }
          }
        }
      }

      if (bestMatch) return bestMatch;

      return s || '角色';
    }

