      }
    }

    // 创建角色对话元素（增强版）
    function createDialogueElement(name, dialogue, skipProcess = false) {
      const normalizedName = normalizeDisplayName(name);

      const config = CHARACTER_CONFIG[normalizedName];
      const avatarHtml = config && config.avatar
        ? `<img class="character-avatar" src="${config.avatar}" alt="${normalizedName}" loading="lazy" decoding="async">`
        : `<div class="character-avatar-placeholder">👤</div>`;

      // 强制移除所有花括号内容（角色名标记）
      dialogue = dialogue.replace(/\{[^}]+\}/g, '');

      const processedDialogue = skipProcess ? dialogue : processDialogueContent(dialogue);
      const nameHtml = generateStyledNameHtml(config, normalizedName);

      return `<div class="dialogue-container char-${normalizedName}">
        <div class="dialogue-bubble">
          <div class="avatar-side">
            ${avatarHtml}
          </div>
          <div class="content-side">
            <div class="character-name">${nameHtml}</div>
            <div class="bubble-text">${processedDialogue}</div>
          </div>
        </div>
      </div>`;
    }

    // 处理对话内容（支持双语格式）
    // Format *...* inside dialogue as darker action/narration text.
    // Keep **...** untouched for the existing global asterisk cleanup.
    function formatDialogueEmphasis(html) {
      const emRegex = /(?<!\*)\*(?!\*)([^*\n]+?)\*(?!\*)/g;
      return String(html || '').replace(emRegex, (match, inner) => {
        return `<em class="dialogue-em">${inner}</em>`;
      });
    }

    function processDialogueContent(dialogue) {
      // 移除对话内容中的角色名标记 {角色名}
      dialogue = dialogue.replace(/\{[^}]+\}/g, '').trim();

      // 支持多种双语格式：
      // 「日文」（中文）、「日文」(中文)、『日文』（中文）、【日文】（中文）
      const patterns = [
        { regex: /「([^」]+)」（([^）]+)）/g, type: 'standard' },
        { regex: /「([^」]+)」\(([^)]+)\)/g, type: 'halfwidth' },
        { regex: /『([^』]+)』（([^）]+)）/g, type: 'alternate' },
        { regex: /【([^】]+)】（([^）]+)）/g, type: 'square' }
      ];

      let result = dialogue;
      patterns.forEach(({ regex }) => {
        result = result.replace(regex, (match, text1, text2) => {
          return `<div class="bilingual-dialogue">
        <div class="primary-text">「${text1}」</div>
        <div class="dialogue-divider"></div>
        <div class="secondary-text">（${text2}）</div>
      </div>`;
        });
      });

      // 如果没有双语格式，且不包含对话引号，则加上引号
      if (result === dialogue &&
        !dialogue.includes('「') && !dialogue.includes('『') &&
        !dialogue.includes('【')) {
        result = `「${dialogue}」`;
      }

      return formatDialogueEmphasis(result);
    }

    function wrapInlineDialogueQuote(segment) {
      if (!segment) return '';
      const pairs = {
        '「': '」',
        '『': '』',
        '【': '】',
        '“': '”',
        '"': '"'
      };
      const open = segment[0];
      const close = segment[segment.length - 1];
      const expectedClose = pairs[open];
      if (!expectedClose || expectedClose !== close || segment.length < 2) {
        return escapeHtmlText(segment);
      }
      const inner = segment.slice(1, -1);
      return `<span class="inline-dialogue-quote"><span class="quote-mark">${escapeHtmlText(open)}</span>${escapeHtmlText(inner)}<span class="quote-mark">${escapeHtmlText(close)}</span></span>`;
    }

    // 非对白正文里的 *...* 旁白强调：转义后包进斜体+变暗的 <em>。
    // 用负向断言避开 **加粗**（双星号仍交给 removeAsterisks 清理），
    // 星号内不允许换行/星号，未配对的孤立星号原样转义输出。
    function escapeWithNarrationEmphasis(text) {
      const src = String(text || '');
      const emRegex = /(?<!\*)\*(?!\*)([^*\n]+?)\*(?!\*)/g;
      let out = '';
      let last = 0;
      let m;
      while ((m = emRegex.exec(src)) !== null) {
        out += escapeHtmlText(src.slice(last, m.index));
        out += '<em class="narration-em">' + escapeHtmlText(m[1]) + '</em>';
        last = m.index + m[0].length;
      }
      out += escapeHtmlText(src.slice(last));
      return out;
    }

    function highlightInlineDialogueQuotes(text) {
      const source = decodeHtmlEntities(String(text || ''));
      const quoteRegex = /「[^」\n]+」|『[^』\n]+』|【[^】\n]+】|“[^”\n]+”|"[^"\n]+"/g;
      let result = '';
      let lastIndex = 0;
      let match;

      while ((match = quoteRegex.exec(source)) !== null) {
        result += escapeWithNarrationEmphasis(source.slice(lastIndex, match.index));
        result += wrapInlineDialogueQuote(match[0]);
        lastIndex = match.index + match[0].length;
      }

      result += escapeWithNarrationEmphasis(source.slice(lastIndex));
      return result;
    }


    const AVATAR_MODAL_COVER_EXCLUDED_NAMES = new Set();

    function toCoverImageUrl(avatarSrc) {
      return String(avatarSrc || '')
        .replace('/%E5%A4%B4%E5%83%8F/', '/%E5%B0%81%E9%9D%A2/')
        .replace(/\/头像\//g, '/封面/');
    }

    function resolveModalImageSource(clickedImg) {
      const fallbackSrc = clickedImg.currentSrc || clickedImg.src;
      if (!clickedImg.classList?.contains('character-avatar')) {
        return { src: fallbackSrc, fallbackSrc };
      }

      const charName = normalizeDisplayName(clickedImg.getAttribute('alt') || '');
      if (!charName || AVATAR_MODAL_COVER_EXCLUDED_NAMES.has(charName)) {
        return { src: fallbackSrc, fallbackSrc };
      }

      const coverSrc = toCoverImageUrl(fallbackSrc);
      return {
        src: coverSrc && coverSrc !== fallbackSrc ? coverSrc : fallbackSrc,
        fallbackSrc
      };
    }

    document.addEventListener('click', function (e) {
      if (e.target.tagName === 'IMG' && e.target.closest('.reading-content')
        && !e.target.closest('.st-chatu8-image-container, .st-chatu8-image-span, span[data-request-id]')) {
        const modal = document.getElementById('imageModal');
        const modalImage = document.getElementById('modalImage');
        const modalImageSource = resolveModalImageSource(e.target);

        // 被点击图片在文档中的绝对位置
        const imgRect = e.target.getBoundingClientRect();
        const scrollY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
        const imgTopAbs = imgRect.top + scrollY;
        const imgCenterAbs = imgTopAbs + imgRect.height / 2;

        // modal的top定位到被点击图片的位置附近
        // 预估modal内容高度，让modal居中于点击图片的中心
        // 先用一个合理的估算值，后续在图片加载后可以微调
        const estimatedH = Math.min(imgRect.height * 1.5, window.innerHeight * 0.8);
        let modalTop = imgCenterAbs - estimatedH / 2;
        if (modalTop < 0) modalTop = 0;

        modal.style.top = modalTop + 'px';
        modal.style.height = Math.max(estimatedH, 400) + 'px';
        modal.classList.add('active');

        // 图片加载完成后，根据实际高度重新调整modal位置
        const adjustPosition = () => {
          const actualH = Math.max(modalImage.offsetHeight + 40, 400);
          let adjustedTop = imgCenterAbs - actualH / 2;
          if (adjustedTop < 0) adjustedTop = 0;
          modal.style.top = adjustedTop + 'px';
          modal.style.height = actualH + 'px';
        };

        modalImage.onload = adjustPosition;
        modalImage.onerror = () => {
          if (modalImageSource.src !== modalImageSource.fallbackSrc) {
            modalImage.onerror = null;
            modalImage.onload = adjustPosition;
            modalImage.src = modalImageSource.fallbackSrc;
          } else {
            adjustPosition();
          }
        };

        modalImage.src = modalImageSource.src;
        modalImage.alt = e.target.alt;

        if (modalImage.complete && modalImage.naturalHeight > 0) {
          requestAnimationFrame(adjustPosition);
        }
      }
    });

    const closeModal = () => {
      const modal = document.getElementById('imageModal');
      const modalImage = document.getElementById('modalImage');
      modal.classList.remove('active');
      modal.style.top = '';
      modal.style.height = '';
      if (modalImage) {
        modalImage.onload = null;
        modalImage.onerror = null;
        modalImage.removeAttribute('src');
        modalImage.alt = '';
      }
    };
    document.getElementById('modalClose')?.addEventListener('click', closeModal);
    document.getElementById('imageModal')?.addEventListener('click', function (e) {
      if (e.target === this || e.target.id === 'modalImage') closeModal();
    });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeModal(); });


    // Unsupported RPG tags are intentionally left as ordinary text.

    function stripNowPlotTags(text) {
      return String(text || '').replace(/<\/?\s*now_plot\s*>/gi, '');
    }

    function processTextContent() {
      const contentDiv = document.getElementById('readingContent');
      if (!contentDiv) return;

      let initialHtml = stripNowPlotTags(contentDiv.innerHTML).trim();
      if (!initialHtml) return;

      // === 保护 markdown 代码块围栏 ```...``` ===
      // 代码块内的 <div>/<style> 等会被浏览器当作真实DOM解析并被后续HTML块提取逻辑抽走，
      // 破坏正文结构。此处先在字符串层面把代码块替换为纯文本占位符，最后再还原为转义后的 <pre><code>。
      const fencedCodeBlocks = [];
      initialHtml = initialHtml.replace(/```[\s\S]*?```/g, (block) => {
        const ph = 'RPCODEFENCE' + fencedCodeBlocks.length + 'FENCEEND';
