      // 卡片标签只认 ASCII 名（LiveRoom / SuddenEvent），大小写随意（正则带 i）：
      // HTML 规范规定 `</` 后必须紧跟 ASCII 字母，否则整段按 bogus comment 吞掉，
      // 所以 `</直播间>` 进 innerHTML 就变成 `<!--直播间-->`，闭合标签根本不存在，
      // 中文标签在这条链路上不可能匹配到。中文名保留在开标签的兼容里没有意义，一并去掉。
      const tagPatterns = [
