          if (match.type === 'image-tag') return renderImageTag(match);
          if (match.type === 'html-img') return createInteractiveImageContainer(match.content);
          if (match.type === 'live-room') return renderLiveRoom(match.content, htmlParts.length);
          if (match.type === 'sudden-event') return renderSuddenEvent(match.content, htmlParts.length);
        } catch (err) {
